    "file": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Accepte un tableau d'objet contenant au moins le nom du fichier utilisateur. Vous pouvez également fournir une chaine de charactères contenant les noms des fichiers séparés par des virgules ou bien un tableau de nom de fichiers. Vous pouvez utiliser l'API « Envoi de fichier » pour envoyer des fichiers. La réponse à ces appels peut-être fournie directement en tant qu'objet ici. Les différentes API sont listées dans la barre latérale gauche." } },
    "singleSelect": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Accepte un nombre entier ou une valeur textuelle représentant l'identifiant de l'option de sélection choisie ou la valeur de l'option. Une valeur nulle signifie qu'aucune option n'est sélectionnée. Dans le cas d'une valeur textuelle, la première option correspondante est sélectionnée." } },
    "multipleSelect": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Accepte un tableau d'entiers mixtes ou de valeurs textuelles représentant chacun l'identifiant ou la valeur de l'option de sélection choisie. Dans le cas d'une valeur textuelle, la première option correspondante est sélectionnée. Vous pouvez envoyer une chaîne de caractères contenant des noms séparé par des virgules. Dans ce cas la chaîne est convertie en une liste de noms." } },
    "phoneNumber": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Accepte un numéro de téléphone d'une longueur maximum de 100 caractères qui doivent être des chiffres, des espaces ou les caractères suivants : Nx,._+*()#=;/- ." } },
